local GardenSeedTapeMaker = {}
local PRODUCTS = {
    iron_gardenseedtape = { name = "Železni trak za seme", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni trak za seme za vrtnarje." },
    bronze_gardenseedtape = { name = "Bronast trak za seme", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast trak za seme za vrtnarje." },
    silver_gardenseedtape = { name = "Srebrn trak za seme", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn trak za seme za vrtnarje." },
    gilded_gardenseedtape = { name = "Pozlačen trak za seme", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen trak za seme za vrtnarje." },
    jewel_set_gardenseedtape = { name = "Draguljast trak za seme", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast trak za seme za vrtnarje." },
    royal_sovereign_gardenseedtape = { name = "Kraljevski suveren trak za seme", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren trak za seme z biseri za krono." },
}
local BUILDINGS = {
    gardenseedtape_workshop = { name = "Gardenseedtape delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    gardenseedtape_house = { name = "Gardenseedtape hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_gardenseedtape_atelier = { name = "Mojstrski gardenseedtape atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_gardenseedtape_palace = { name = "Suverena gardenseedtape palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GardenSeedTapeMaker.ironStock=12; GardenSeedTapeMaker.bronzeStock=10; GardenSeedTapeMaker.woodStock=16; GardenSeedTapeMaker.leatherStock=10; GardenSeedTapeMaker.silverStock=8; GardenSeedTapeMaker.goldStock=6; GardenSeedTapeMaker.jewelStock=4; GardenSeedTapeMaker.pearlStock=4
GardenSeedTapeMaker.productStock = {}; GardenSeedTapeMaker.buildings = {}; GardenSeedTapeMaker.maker = nil; GardenSeedTapeMaker.activeMaking = {}; GardenSeedTapeMaker.totalProducts = 0; GardenSeedTapeMaker.dayTimer = 0
function GardenSeedTapeMaker.init() GardenSeedTapeMaker.ironStock=12; GardenSeedTapeMaker.bronzeStock=10; GardenSeedTapeMaker.woodStock=16; GardenSeedTapeMaker.leatherStock=10; GardenSeedTapeMaker.silverStock=8; GardenSeedTapeMaker.goldStock=6; GardenSeedTapeMaker.jewelStock=4; GardenSeedTapeMaker.pearlStock=4; GardenSeedTapeMaker.productStock={}; GardenSeedTapeMaker.buildings={}; GardenSeedTapeMaker.maker=nil; GardenSeedTapeMaker.activeMaking={}; GardenSeedTapeMaker.totalProducts=0; GardenSeedTapeMaker.dayTimer=0; print("[GardenSeedTapeMaker] Royal Garden Seed Tape Maker System initialized (6 products, 4 buildings)") end
function GardenSeedTapeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenSeedTapeMaker.maker={name=n or ("Trakar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Trakar najet: %s (spretnost: %d)",GardenSeedTapeMaker.maker.name,s),"success") end; return true end
function GardenSeedTapeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenSeedTapeMaker.build(id) local ok,e=GardenSeedTapeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenSeedTapeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenSeedTapeMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenSeedTapeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenSeedTapeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenSeedTapeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenSeedTapeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenSeedTapeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenSeedTapeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenSeedTapeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenSeedTapeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenSeedTapeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenSeedTapeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenSeedTapeMaker.buildings==0 then return false,"Potrebna trakna delavnica" end; if not GardenSeedTapeMaker.maker then return false,"Potreben trakar" end; return true end
function GardenSeedTapeMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenSeedTapeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenSeedTapeMaker.ironStock=GardenSeedTapeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenSeedTapeMaker.bronzeStock=GardenSeedTapeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenSeedTapeMaker.woodStock=GardenSeedTapeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenSeedTapeMaker.leatherStock=GardenSeedTapeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenSeedTapeMaker.silverStock=GardenSeedTapeMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenSeedTapeMaker.goldStock=GardenSeedTapeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenSeedTapeMaker.jewelStock=GardenSeedTapeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenSeedTapeMaker.pearlStock=GardenSeedTapeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenSeedTapeMaker.maker then t=math.max(1,t-math.floor(GardenSeedTapeMaker.maker.skill/13)) end; table.insert(GardenSeedTapeMaker.activeMaking,{id="gardenseedtape_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenSeedTapeMaker.completeMaking(m) local q=1.0+(GardenSeedTapeMaker.getQualityBonus()/100); if GardenSeedTapeMaker.maker then q=q+(GardenSeedTapeMaker.maker.skill/140) end; q=math.min(2.5,q); GardenSeedTapeMaker.productStock[m.productType]=(GardenSeedTapeMaker.productStock[m.productType] or 0)+m.quantity; GardenSeedTapeMaker.totalProducts=GardenSeedTapeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenSeedTapeMaker.maker then GardenSeedTapeMaker.maker.itemsMade=GardenSeedTapeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenSeedTapeMaker.maker.skill=math.min(100,GardenSeedTapeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Trak izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardenseedtape.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenSeedTapeMaker.update(dt) if not _G.state then return end; GardenSeedTapeMaker.dayTimer=GardenSeedTapeMaker.dayTimer+dt; if GardenSeedTapeMaker.dayTimer>=30 then GardenSeedTapeMaker.dayTimer=0; for i=#GardenSeedTapeMaker.activeMaking,1,-1 do local m=GardenSeedTapeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenSeedTapeMaker.completeMaking(m); table.remove(GardenSeedTapeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenSeedTapeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenSeedTapeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenSeedTapeMaker.getStats() return {ironStock=GardenSeedTapeMaker.ironStock,bronzeStock=GardenSeedTapeMaker.bronzeStock,woodStock=GardenSeedTapeMaker.woodStock,leatherStock=GardenSeedTapeMaker.leatherStock,silverStock=GardenSeedTapeMaker.silverStock,goldStock=GardenSeedTapeMaker.goldStock,jewelStock=GardenSeedTapeMaker.jewelStock,pearlStock=GardenSeedTapeMaker.pearlStock,productStock=GardenSeedTapeMaker.productStock,numBuildings=#GardenSeedTapeMaker.buildings,hasMaker=GardenSeedTapeMaker.maker~=nil,makerName=GardenSeedTapeMaker.maker and GardenSeedTapeMaker.maker.name or "—",makerSkill=GardenSeedTapeMaker.maker and GardenSeedTapeMaker.maker.skill or 0,activeMaking=#GardenSeedTapeMaker.activeMaking,totalProducts=GardenSeedTapeMaker.totalProducts} end
return GardenSeedTapeMaker
